<?php
declare(strict_types=1);
namespace Dreamsmith\Campaign\Data;
use Dreamsmith\Campaign\Authentication\AuthenticationService;use Dreamsmith\Campaign\Http\Request;use Dreamsmith\Campaign\Http\Response;use Dreamsmith\Campaign\Http\Router;use Dreamsmith\Campaign\Presentation\FlashBag;use Dreamsmith\Campaign\Presentation\ShellRenderer;use Dreamsmith\Campaign\Security\Csrf;
final class DataController{
 public function __construct(private readonly AuthenticationService $auth,private readonly DataService $service,private readonly ShellRenderer $shell,private readonly FlashBag $flash,private readonly Csrf $csrf,private readonly Router $router){}
 public function index():Response{$u=$this->user();if($u instanceof Response)return $u;return $this->shell->owner('data/index.php',['importUrl'=>$this->router->url('data.import'),'exportUrl'=>$this->router->url('data.export'),'exports'=>$this->service->exportOptions()],$u,'Data tools','data.index');}
 public function importForm():Response{$u=$this->user();if($u instanceof Response)return $u;return $this->shell->owner('data/import.php',['csrfToken'=>$this->csrf->token(),'previewUrl'=>$this->router->url('data.import.preview'),'templateUrl'=>$this->router->url('data.import.template'),'exportUrl'=>$this->router->url('data.export')],$u,'Import prospects','data.index');}
 public function interactionForm():Response{$u=$this->user();if($u instanceof Response)return $u;return $this->shell->owner('data/import-interactions.php',['csrfToken'=>$this->csrf->token(),'previewUrl'=>$this->router->url('data.interactions.preview'),'templateUrl'=>$this->router->url('data.interactions.template')],$u,'Import interactions','data.index');}
 public function interactionTemplate():Response{$u=$this->user();if($u instanceof Response)return $u;return new Response(implode(',',$this->service->interactionHeaders())."\r\n",200,['Content-Type'=>'text/csv; charset=utf-8','Content-Disposition'=>'attachment; filename="interaction-import-template.csv"']);}
 public function interactionPreview(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$preview=$this->service->previewInteractions(is_array($q->files['csv']??null)?$q->files['csv']:null,(int)$u['id']);}catch(\InvalidArgumentException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.interactions.import'));}return $this->shell->owner('data/preview.php',['preview'=>$preview,'csrfToken'=>$this->csrf->token(),'commitUrl'=>$this->router->url('data.interactions.commit'),'cancelUrl'=>$this->router->url('data.import.cancel'),'importUrl'=>$this->router->url('data.interactions.import')],$u,'Review interaction import','data.index');}
 public function interactionCommit(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$count=$this->service->commitInteractions((string)($q->body['preview_token']??''),(int)$u['id'],$q->requestId);$this->flash->add('success',"Imported {$count} interactions.");}catch(\DomainException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.interactions.import'));}return Response::redirect($this->router->url('data.index'));}
 public function followUpForm():Response{$u=$this->user();if($u instanceof Response)return $u;return $this->shell->owner('data/import-follow-ups.php',['csrfToken'=>$this->csrf->token(),'previewUrl'=>$this->router->url('data.followups.preview'),'templateUrl'=>$this->router->url('data.followups.template')],$u,'Import follow-ups','data.index');}
 public function followUpTemplate():Response{$u=$this->user();if($u instanceof Response)return $u;return new Response(implode(',',$this->service->followUpHeaders())."\r\n",200,['Content-Type'=>'text/csv; charset=utf-8','Content-Disposition'=>'attachment; filename="follow-up-import-template.csv"']);}
 public function followUpPreview(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$preview=$this->service->previewFollowUps(is_array($q->files['csv']??null)?$q->files['csv']:null,(int)$u['id']);}catch(\InvalidArgumentException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.followups.import'));}return $this->shell->owner('data/preview.php',['preview'=>$preview,'csrfToken'=>$this->csrf->token(),'commitUrl'=>$this->router->url('data.followups.commit'),'cancelUrl'=>$this->router->url('data.import.cancel'),'importUrl'=>$this->router->url('data.followups.import')],$u,'Review follow-up import','data.index');}
 public function followUpCommit(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$count=$this->service->commitFollowUps((string)($q->body['preview_token']??''),(int)$u['id'],$q->requestId);$this->flash->add('success',"Imported {$count} follow-ups.");}catch(\DomainException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.followups.import'));}return Response::redirect($this->router->url('work.index'));}
 public function template():Response{$u=$this->user();if($u instanceof Response)return $u;$body=implode(',',$this->service->headers())."\r\n";return new Response($body,200,['Content-Type'=>'text/csv; charset=utf-8','Content-Disposition'=>'attachment; filename="prospect-import-template.csv"','Cache-Control'=>'no-store']);}
 public function preview(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$preview=$this->service->preview(is_array($q->files['csv']??null)?$q->files['csv']:null,(int)$u['id']);}catch(\InvalidArgumentException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.import'));}return $this->shell->owner('data/preview.php',['preview'=>$preview,'csrfToken'=>$this->csrf->token(),'commitUrl'=>$this->router->url('data.import.commit'),'cancelUrl'=>$this->router->url('data.import.cancel'),'importUrl'=>$this->router->url('data.import')],$u,'Review import','data.index');}
 public function commit(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$count=$this->service->commit((string)($q->body['preview_token']??''),(int)$u['id'],$q->requestId);$this->flash->add('success',"Imported {$count} prospects.");}catch(\DomainException $e){$this->flash->add('error',$e->getMessage());return Response::redirect($this->router->url('data.import'));}return Response::redirect($this->router->url('prospects.index'));}
 public function cancel(Request $q):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);$this->service->cancel();$this->flash->add('info','Import preview discarded.');return Response::redirect($this->router->url('data.import'));}
 public function exportForm():Response{$u=$this->user();if($u instanceof Response)return $u;return $this->shell->owner('data/export.php',['csrfToken'=>$this->csrf->token(),'exportUrl'=>$this->router->url('data.export.download'),'importUrl'=>$this->router->url('data.import'),'exports'=>$this->service->exportOptions()],$u,'Export campaign data','data.index');}
 public function export(Request $q,string $type):Response{$u=$this->user();if($u instanceof Response)return $u;if(!$this->csrf->verify($q->body['_csrf']??null))return Response::html('Forbidden',403);try{$export=$this->service->export($type);}catch(\InvalidArgumentException $e){return Response::html('Export not found.',404);}return new Response($export['body'],200,['Content-Type'=>'text/csv; charset=utf-8','Content-Disposition'=>'attachment; filename="'.$export['filename'].'"','Cache-Control'=>'no-store']);}
 private function user():array|Response{return $this->auth->user()??Response::redirect($this->router->url('login.form').'?return=dashboard',302);}
}
